package com.purchasing.service;
import com.purchasing.entity.*; import com.purchasing.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class PurchaseOrderService { final PurchaseOrderRepository repo; final PurchasingTools tools; public PurchaseOrderService(PurchaseOrderRepository r,PurchasingTools t){repo=r;tools=t;} public PurchaseOrder create(Product p,Supplier s,int q){return repo.save(new PurchaseOrder(p,s,q));} public Map<String,Object> validate(PurchaseOrder po){return validate(po,tools.getBudget(),po.product.storageCapacity,po.product.currentInventory,Math.max(0,tools.getOpenPurchaseOrders(po.product)-po.quantity),po.supplier.minimumOrderQuantity);} public Map<String,Object> validate(PurchaseOrder po,java.math.BigDecimal budget,int storage,int currentInventory,int openOrders,int minimumOrderQuantity){List<String> issues=new ArrayList<>(); if(po.quantity<=0)issues.add("Quantity must be positive"); if(po.quantity<minimumOrderQuantity)issues.add("Supplier MOQ is not satisfied"); if(po.quantity>po.supplier.availableQuantity)issues.add("Supplier availability is insufficient"); if(tools.calculatePurchaseCost(po.product,po.quantity).compareTo(budget)>0)issues.add("Purchase order exceeds available budget"); if(currentInventory+openOrders+po.quantity>storage)issues.add("Purchase order exceeds storage capacity"); boolean valid=issues.isEmpty(); po.status=valid?"VALIDATED":"REVIEW_REQUIRED"; repo.save(po); return Map.of("valid",valid,"status",valid?"PASSED":"FAILED","issues",issues); } public PurchaseOrder get(Long id){return repo.findById(id).orElseThrow();} }
